// adding a third currency to the checkout
 function formatPrice(cents: number, currency: string): string {
   if (currency === 'USD') return '$' + (cents / 100).toFixed(2);
   if (currency === 'EUR') return '€' + (cents / 100).toFixed(2);
+  if (currency === 'GBP') return '£' + (cents / 100).toFixed(2);
   return cents.toString();
 }

